contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 id, uint256 value, bytes memory data) public payable {
        require(recipient != address(0), "zero recipient");
        require(recipient != address(this), "self recipient");

        c.pause();

        uint256 senderBalanceBefore = c.balanceOf(address(this), id);
        uint256 recipientBalanceBefore = c.balanceOf(recipient, id);
        uint256 cEthBalanceBefore = address(c).balance;

        bool transferReverted;
        try c.safeTransferFrom(address(this), recipient, id, value, data) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        uint256 senderBalanceAfter = c.balanceOf(address(this), id);
        uint256 recipientBalanceAfter = c.balanceOf(recipient, id);
        uint256 cEthBalanceAfter = address(c).balance;

        assert(transferReverted);
        assert(senderBalanceBefore == senderBalanceAfter);
        assert(recipientBalanceBefore == recipientBalanceAfter);
        assert(cEthBalanceBefore == cEthBalanceAfter);
    }

    receive() external payable {}
}

