contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner1, address newOwner2, bool accept1) public {
        require(newOwner1 != address(0));
        require(newOwner2 != address(0));

        address ownerBefore = c.owner();
        c.transferOwnership(newOwner1);
        address ownerAfterTransfer = c.owner();
        address pendingAfterTransfer = c.pendingOwner();

        bool accepted;
        if (accept1) {
            require(pendingAfterTransfer != address(0), "no pending owner to accept");
            c.acceptOwnership();
            accepted = true;
        } else {
            c.transferOwnership(newOwner2);
            address ownerAfterTransfer2 = c.owner();
            address pendingAfterTransfer2 = c.pendingOwner();
            assert(ownerAfterTransfer2 == ownerAfterTransfer);
            assert(pendingAfterTransfer2 == newOwner2);
            accepted = false;
        }

        if (!accepted) {
            assert(ownerAfterTransfer == ownerBefore);
            assert(pendingAfterTransfer == newOwner1);
        } else {
            assert(c.owner() == newOwner1);
            assert(c.pendingOwner() == address(0));
        }
    }

    receive() external payable {}
}

