        address ownerBefore = c.owner();

        c.transferOwnership(newOwner);
        address ownerAfterTransfer = c.owner();
        address pendingAfterTransfer = c.pendingOwner();

        c.acceptOwnership();

        address ownerAfterAccept = c.owner();
        address pendingAfterAccept = c.pendingOwner();

        c.transferOwnership(other);
        address ownerAfterSecondTransfer = c.owner();
        address pendingAfterSecondTransfer = c.pendingOwner();

        assert(
            ownerAfterTransfer == ownerBefore &&
            pendingAfterTransfer == newOwner &&
            ownerAfterAccept == newOwner &&
            pendingAfterAccept == address(0) &&
            ownerAfterSecondTransfer == newOwner &&
            pendingAfterSecondTransfer == other
        );
    }

    receive() external payable {}
}

